import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {readFile} from 'node:fs/promises';
const html=await readFile('ui/index.html','utf8'),script=[...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].at(-1)[1];
function setup(storage,withExample=true){const nodes=new Map(),handlers={};const node=id=>{if(!nodes.has(id))nodes.set(id,{id:id.replace(/^#/,''),value:'',textContent:'',innerHTML:'',dataset:{},attrs:{},disabled:false,addEventListener(){},setAttribute(k,v){this.attrs[k]=v},removeAttribute(k){delete this.attrs[k]},scrollIntoView(){},click(){},closest(sel){if(sel==='button')return this.tag==='button'?this:null;if(sel==='[data-step]')return this.dataset.step!==undefined?this:null;if(sel==='button[data-step]')return this.tag==='button'&&this.dataset.step!==undefined?this:null;if(sel==='[data-sc]')return this.dataset.sc!==undefined?this:null;return null}});return nodes.get(id)};const ctx={document:{querySelector:node,querySelectorAll:sel=>sel==='input[name="billParticipant"]:checked'?['#billShare1','#billShare2'].map(node):[],addEventListener:(type,f)=>(handlers[type]||=[]).push(f),documentElement:{dataset:{}},createElement:()=>({click(){}})},window:{print(){},localStorage:storage},console,Blob,URL,btoa,atob,setTimeout,clearTimeout,fetch:async()=>({ok:true,json:async()=>({aiReady:false,paypalReady:false,merchantMember:'Rafi',bdtPerUsd:122})}),navigator:{},matchMedia:()=>({matches:false})};vm.createContext(ctx);vm.runInContext(script,ctx);const run=code=>vm.runInContext(code,ctx);if(withExample)run("members=[{name:'Rafi',phone:'',pp:''},{name:'Nusrat',phone:'',pp:''},{name:'Tanvir',phone:'',pp:''},{name:'Mim',phone:'',pp:''}];renderMembers();$('#txt').value=SC[0]");async function click(id,dataset={}){const target={...node('#'+id),tag:'button',dataset};for(const h of handlers.click||[])await h({target})}async function change(dataset,value,checked){for(const h of handlers.change||[])await h({target:{dataset,value,checked}})}return{run,node,click,change,handlers}}
test('sample notes require review and produce the correct plan',async()=>{const ui=setup();ui.run('run()');assert(ui.node('#out').innerHTML.includes('Review your ledger'));assert.equal(ui.run('res'),null);await ui.click('confirm');assert.equal(ui.run('res.tx.length'),3);assert.equal(ui.run('res.bal.Rafi'),1600);assert(ui.node('#out').innerHTML.includes('Payments to settle'));assert(!ui.node('#out').innerHTML.includes('PayPal sandbox checkout</button>'))});
