test('custom bill shares validate totals and survive draft restoration',async()=>{const store=memoryStorage(),ui=setup(store,false);ui.run("members[0].name='A';members[1].name='B';$('#manualStart').onclick()");await ui.change({review:'expense',index:'0',field:'amount'},'600');await ui.change({split:'0'},'custom');await ui.change({share:'0',shareIndex:'0'},'200');await ui.change({share:'0',shareIndex:'1'},'399');await ui.click('confirm');assert.equal(ui.run('res'),null);assert(ui.node('#reviewStatus').textContent.includes('Custom shares'));await ui.change({share:'0',shareIndex:'1'},'400');ui.run("$('#saveDraft').onclick()");const reload=setup(store,false);reload.run("$('#restoreDraft').onclick()");assert.equal(reload.run('draft.expenses[0].shares[1]'),400);await reload.click('confirm');assert.equal(reload.run('res.tx[0].amt'),400)});
