test('uncertain notes can be corrected without discarding recognized bills',async()=>{const ui=setup();ui.run("draft={expenses:[{payer:'Rafi',amount:400,description:'Known',participants:['Rafi','Mim']}],debts:[],unknown:['Dinner total unclear']};review()");await ui.click('resolve',{resolveUnknown:'0'});assert.equal(ui.run('draft.expenses[0].amount'),400);assert.equal(ui.run('draft.expenses.length'),2);assert.equal(ui.run('draft.unknown.length'),0);await ui.click('confirm');assert.equal(ui.run('res'),null);await ui.change({review:'expense',index:'1',field:'amount'},'600');await ui.click('confirm');assert.equal(ui.run('res.total'),1000)});
