test('complete trip with custom shares, partial payment and remaining summary',async()=>{const ui=setup(undefined,false);ui.run("$('#tryTour').onclick()");await ui.change({split:'0'},'custom');for(const [j,v] of [1000,1500,2000,1500].entries())await ui.change({share:'0',shareIndex:String(j)},String(v));await ui.click('confirm');assert.equal(ui.run('res.total'),11700);assert.equal(ui.run('res.bal.Tanvir'),2425);const i=ui.run("res.tx.findIndex(t=>t.from==='Nusrat')");assert(i>=0);ui.node('#partial'+i).value='500';await ui.click('partial',{partial:String(i)});assert.equal(ui.run('res.bal.Nusrat'),-975);ui.run('navigator.clipboard={writeText:async value=>{globalThis.shared=value}}');await ui.click('copySummary');assert(ui.run('shared').includes('975.00'));assert(ui.run('shared').includes('not provider verified'));assert.equal(ui.run('data.debts.filter(d=>d.kind===\'repayment\').length'),1)});

