test('automatic motion respects reduced-motion without an extra UI control',()=>{const ui=setup(undefined,false);ui.run("globalThis.animated=0;$('#expenseStep').animate=()=>{animated++};goStep('stepInput')");assert.equal(ui.run('animated'),1);ui.run("setMotionPreference(false);goStep('stepGroup');goStep('stepInput')");assert.equal(ui.run('animated'),1);assert(!html.includes('id="motionToggle"'));});
test('transfer routes show full sender and recipient and recording restores button focus',async()=>{const ui=setup(undefined,false);ui.run("members[0].name='Shaon';members[1].name='Saiful';$('#manualStart').onclick();draft.expenses[0].amount=600");await ui.click('confirm');const view=ui.node('#out').innerHTML;assert(view.includes('<small>From</small><b>Saiful</b>'));assert(view.includes('<small>To</small><b>Shaon</b>'));ui.run(`globalThis.focusReturned=false;$('[data-paid="0"]').focus=()=>{focusReturned=true}`);await ui.click('record',{paid:'0'});assert.equal(ui.run('focusReturned'),true);assert.equal(ui.run('paid[0]'),true);assert(ui.node('#out').innerHTML.includes('All payments recorded.'));});

test('illustration replay preserves the button and respects disabled motion',()=>{const ui=setup();ui.run("globalThis.replayed=0;$('#replayIllustration').getAnimations=()=>[{cancel(){replayed++},play(){replayed++}}];$('#replayIllustration').onclick()");assert.equal(ui.run('replayed'),2);ui.run("setMotionPreference(false);$('#replayIllustration').onclick()");assert.equal(ui.run('replayed'),2);assert(!html.includes('this.replaceWith(n)'));assert(!html.includes('MutationObserver'));assert(!html.includes('#fxToggle,#motionToggle{display:none'));});

test('AI extraction stays retryable after unavailable config and blocks duplicate requests',async()=>{const ui=setup();ui.run("globalThis.AbortSignal={timeout:()=>undefined};fetch=async()=>({ok:true,json:async()=>({aiReady:true,visionReady:true})})");await ui.run('refreshAI()');assert.equal(ui.run('aiConfig.aiReady'),true);assert.equal(ui.node('#readChat').disabled,false);ui.run("chatBusy=true");await ui.run("$('#readChat').onclick()");assert.equal(ui.run('draft'),null);ui.run("chatBusy=false;fetch=async()=>{throw Error('offline')}");await ui.run('refreshAI()');assert.equal(ui.node('#readChat').disabled,false);assert(ui.node('#aiStatus').textContent.includes('retry'));});

test('backups retain selected wallets and reject unknown payment methods',()=>{const ui=setup();ui.run("members[0].paymentKind='nagad';members[0].payments={nagad:{number:'01700000000',url:''}};globalThis.snapshot=draftSnapshot();validateSavedDraft(snapshot);importSnapshot(snapshot)");assert.equal(ui.run('members[0].paymentKind'),'nagad');assert.equal(ui.run("members[0].payments.nagad.number"),'01700000000');assert.throws(()=>ui.run("snapshot.members[0].paymentKind='unknown';validateSavedDraft(snapshot)"),/payment method/);});
test('adding a name checks duplicates after trimming existing input',()=>{const ui=setup();ui.run("members[0].name=' Rafi ';$('#newName').value='rafi';$('#addM').onclick()");assert.equal(ui.run('members.length'),4);assert(ui.node('#validationMessage').textContent.includes('already'));});

test('unclear notes can become an editable previous debt without guessing amounts',async()=>{const ui=setup();ui.run("draft={expenses:[],debts:[],unknown:['Rafi Nusrat ke taka debe']};review()");assert(ui.node('#out').innerHTML.includes('Enter as previous debt'));await ui.click('debt',{resolveDebt:'0'});assert.equal(ui.run('draft.unknown.length'),0);assert.equal(ui.run('draft.debts[0].amount'),0);assert.equal(ui.run('draft.debts[0].note'),'Rafi Nusrat ke taka debe');await ui.click('confirm');assert.equal(ui.run('res'),null);assert(ui.node('#out').innerHTML.includes('Original note:'));});
test('local reading flags several statements on one line rather than dropping later amounts',()=>{const ui=setup();const r=ui.run("localParse('Rafi paid 500 for dinner, Nusrat paid 200 for snacks')");assert.equal(r.expenses.length,0);assert.equal(r.unknown.length,1);assert.equal(ui.run("localParse('Rafi paid 500 for dinner; Nusrat paid 200 for snacks').expenses.length"),2);});
